11	{"schema":"brainstorm/v1","id":"BS-2026-05-13-wh008","ts":"2026-05-13T17:00:00Z","title":"winsorize_heavy_tails","hypothesis":"AveRooms, AveBedrms, AveOccup, and Population have heavy right tails with extreme outliers (e.g., AveRooms > 100, AveOccup > 1000 in a few rows) that wreck OLS by dragging the fit. Winsorizing these columns at the 99th percentile (or capping to a fixed threshold) should improve baseline R² with no new feature semantics — pure preprocessing orthogonal to ratio/log/interaction families.","source":{"kind":"planner","ref":"explore_axis:preprocessing","finding_id":null},"feature_family_name_hint":"winsorize_heavy_tails","row_grain":"(row_id)","estimated_cost_dollars":0.4,"estimated_implement_minutes":15,"content_hash":"0f9da3d90fee4a17af7a42a3b43cbe75a8e6512605739f32e8f5d2cbf660217d","embedding_hash":null,"embedding_uri":null,"tier":"T1","tier_score":0.72,"tier_rationale":"EXPLORE: highest novelty — opens a preprocessing axis the queue has zero coverage in. Medium-high signal: heavy tails on AveOccup/AveRooms are documented in this dataset and disproportionately damage OLS. Cheap to implement (per-column quantile cap).","status":"queued","iteration_id":null,"run_id":null,"iteration_history":[]}
